// Authentication Service with JWT and Session Management

// Mock user database with account status and roles
const MOCK_USERS = {
  'SA001': { name: 'Super Admin', password: 'super123', role: 'super_admin', email: 'superadmin@company.com', status: 'active' },
  'A001': { name: 'Admin User', password: 'admin123', role: 'admin', email: 'admin@company.com', status: 'active' },
  'A002': { name: 'Admin 2', password: 'admin123', role: 'admin', email: 'admin2@company.com', status: 'active' },
  'M001': { name: 'Manager User', password: 'manager123', role: 'manager', email: 'manager@company.com', status: 'active' },
  'M002': { name: 'Manager 2', password: 'manager123', role: 'manager', email: 'manager2@company.com', status: 'active' },
  'E001': { name: 'Employee User', password: 'emp123', role: 'employee', email: 'employee@company.com', status: 'active' },
  'E002': { name: 'Employee 2', password: 'emp123', role: 'employee', email: 'employee2@company.com', status: 'inactive' },
  'super': { name: 'Super Admin', password: 'super123', role: 'super_admin', email: 'superadmin@company.com', status: 'active' },
  'admin': { name: 'Admin User', password: 'admin123', role: 'admin', email: 'admin@company.com', status: 'active' },
  'manager': { name: 'Manager User', password: 'manager123', role: 'manager', email: 'manager@company.com', status: 'active' },
  'employee': { name: 'Employee User', password: 'emp123', role: 'employee', email: 'employee@company.com', status: 'active' },
};

// Simple JWT token generation (in production, use proper JWT library)
const generateToken = (userId, role) => {
  const payload = {
    userId,
    role,
    iat: Math.floor(Date.now() / 1000),
    exp: Math.floor(Date.now() / 1000) + (24 * 60 * 60) // 24 hours
  };
  
  // Simple base64 encoding (not secure, for demo purposes)
  return btoa(JSON.stringify(payload));
};

// Verify token
const verifyToken = (token) => {
  try {
    const payload = JSON.parse(atob(token));
    const now = Math.floor(Date.now() / 1000);
    
    if (payload.exp < now) {
      return null; // Token expired
    }
    
    return payload;
  } catch (error) {
    return null;
  }
};

// Login service
export const loginUser = (employeeId, password) => {
  const id = employeeId.trim().toLowerCase();
  const user = MOCK_USERS[id];
  
  if (!user) {
    return {
      success: false,
      error: 'User not found'
    };
  }
  
  // For demo purposes: accept any password (in production, use bcrypt or similar)
  // In a real system, the password would be validated against a hashed password
  if (!password || password.trim() === '') {
    return {
      success: false,
      error: 'Please enter a password'
    };
  }
  
  // Check account status
  if (user.status === 'inactive') {
    return {
      success: false,
      error: 'Account is inactive. Please contact administrator.'
    };
  }
  
  // Generate JWT token
  const token = generateToken(id, user.role);
  const sessionId = 'sess_' + Math.random().toString(36).substr(2, 9);
  
  const authData = {
    employeeId: id,
    employeeName: user.name,
    userRole: user.role,
    email: user.email,
    status: user.status,
    token,
    sessionId,
    isAdmin: user.role === 'admin',
    isManager: user.role === 'manager',
    loginTime: new Date().toISOString()
  };
  
  // Store in sessionStorage (more secure than localStorage)
  sessionStorage.setItem('authToken', token);
  sessionStorage.setItem('sessionId', sessionId);
  sessionStorage.setItem('authData', JSON.stringify(authData));
  
  // Also store in localStorage for persistence
  localStorage.setItem('authToken', token);
  localStorage.setItem('authData', JSON.stringify(authData));
  
  return {
    success: true,
    user: authData
  };
};

// Verify session
export const verifySession = () => {
  const token = sessionStorage.getItem('authToken') || localStorage.getItem('authToken');
  const authData = sessionStorage.getItem('authData') || localStorage.getItem('authData');
  
  if (!token || !authData) {
    return null;
  }
  
  const payload = verifyToken(token);
  if (!payload) {
    logoutUser();
    return null;
  }
  
  try {
    return JSON.parse(authData);
  } catch (error) {
    return null;
  }
};

// Logout
export const logoutUser = () => {
  sessionStorage.removeItem('authToken');
  sessionStorage.removeItem('sessionId');
  sessionStorage.removeItem('authData');
  localStorage.removeItem('authToken');
  localStorage.removeItem('authData');
};

// Check if user has required role
export const hasRole = (user, requiredRole) => {
  if (!user) return false;
  
  if (requiredRole === 'admin') {
    return user.userRole === 'admin';
  } else if (requiredRole === 'manager') {
    return user.userRole === 'admin' || user.userRole === 'manager';
  } else if (requiredRole === 'employee') {
    return true; // All authenticated users can access employee features
  }
  
  return false;
};

// Get user permissions based on role
export const getPermissions = (role) => {
  const permissions = {
    admin: {
      viewAttendance: true,
      manageSalary: true,
      manageEmployees: true,
      manageUsers: true,
      viewReports: true,
      editCompanySettings: true
    },
    manager: {
      viewAttendance: true,
      manageSalary: true,
      manageEmployees: true,
      manageUsers: false,
      viewReports: true,
      editCompanySettings: false
    },
    employee: {
      viewAttendance: true, // own only
      manageSalary: true, // own only
      manageEmployees: false,
      manageUsers: false,
      viewReports: false,
      editCompanySettings: false
    }
  };
  
  return permissions[role] || {};
};

// Forgot password service
export const sendPasswordResetEmail = (email) => {
  const user = Object.entries(MOCK_USERS).find(([_, u]) => u.email === email);
  
  if (!user) {
    return {
      success: false,
      error: 'Email not found in the system'
    };
  }
  
  // In production, send actual email with reset link
  console.log(`Password reset link would be sent to: ${email}`);
  
  // Generate reset token
  const resetToken = 'reset_' + Math.random().toString(36).substr(2, 9);
  localStorage.setItem(`passwordReset_${email}`, resetToken);
  
  return {
    success: true,
    message: 'Password reset link has been sent to your email',
    email
  };
};

// Reset password
export const resetPassword = (email, newPassword, resetToken) => {
  const storedToken = localStorage.getItem(`passwordReset_${email}`);
  
  if (storedToken !== resetToken) {
    return {
      success: false,
      error: 'Invalid reset token'
    };
  }
  
  const user = Object.entries(MOCK_USERS).find(([_, u]) => u.email === email);
  if (user) {
    MOCK_USERS[user[0]].password = newPassword;
    localStorage.removeItem(`passwordReset_${email}`);
    
    return {
      success: true,
      message: 'Password has been reset successfully'
    };
  }
  
  return {
    success: false,
    error: 'Unable to reset password'
  };
};
